/**
 * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED, VOID or DELETED claim, or a closed
 * period.
 */
@Transactional
public Claim addProof(String sheetId, String user, Long id) {
    Claim claim = claims.findForUpdate(id, sheetId)
            .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
    if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
            || claim.getStatus() == ClaimStatus.DELETED) {
        throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
    }
    periods.requireOpen(sheetId, claim.getDueBy());
    Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
            .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
    claim.addProof();
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
            + " proofs=" + saved.getProofs());
    return saved;
}

/**
 * Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes the sheet's today.
 * Refused for any other status, and for a claim already reminded on the sheet's today. While the sheet has an
 * escalation gap, a claim never escalated whose previous reminder was at least that many days before the sheet's
 * today is escalated: ESCALATE is written after the REMIND line.
 */
@Transactional
public Claim remind(String sheetId, String user, Long id) {
    Claim claim = claims.findForUpdate(id, sheetId)
            .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
    if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
        throw new ClaimRemindException(id, "it is " + claim.getStatus()
                + ", only an OPEN or PENDING claim can be reminded");
    }
    LocalDate today = sheets.today(sheetId);
    if (today.equals(claim.getRemindedOn())) {
        throw new ClaimRemindException(id, "it was already reminded on " + today);
    }
    Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
            .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
    Integer gap = sheets.escalateAfter(sheetId);
    boolean escalate = gap != null && !claim.isEscalated() && claim.getRemindedOn() != null
            && !claim.getRemindedOn().plusDays(gap).isAfter(today);
    claim.setRemindedOn(today);
    if (escalate) {
        claim.setEscalated(true);
    }
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("REMIND", user, person, saved) + numberOf(saved.getNumber()));
    if (escalate) {
        audit.recordOnCommit(record("ESCALATE", user, person, saved) + numberOf(saved.getNumber()));
    }
    return saved;
}

/**
 * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date (its person's
 * grade's own then, else the sheet's) cannot be settled or approved while it has no proof; refused then. A due of
 * n/a is within any threshold.
 */
private void requireProof(String sheetId, Person person, Claim claim) {
    BigDecimal threshold = settings.get(sheetId).proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
    if (threshold == null || claim.getProofs() > 0) {
        return;
    }
    BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
    if (due != null && due.compareTo(threshold) > 0) {
        throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
                + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
    }
}

/**

/**
 * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
 * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
 * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
 * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
 * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
 * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
 * it has; and the number of the claim it was split off (null unless it was); and the user whose open editor locks
 * it (null when not locked); and the last day it was reminded (null when never); and its external reference (null
 * when it has none); and its tags, sorted and comma separated (null when it has none); and the reason it was voided
 * with (null when none); and its comments, oldest first; and the bulk settle batch that settled it (null when none);
 * and the stamp a forward-only rate is matched against (it sees one whose forwardAfter is below it); and the day it
 * last went to REVIEW (null when it never did); and whether a steward waived its late charge.
 */
public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
        LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
        int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref,
        String tags, String voidReason, List<ClaimCommentView> comments, Long settleBatch,
        List<ClaimLineView> lines, Long rateStamp, LocalDate reviewOn, boolean waived) {

    /** A claim with no comments or lines yet. */
    static ClaimView of(Claim claim, List<ClaimLog> log) {
        return of(claim, log, List.of(), List.of());
    }

    static ClaimView of(Claim claim, List<ClaimLog> log, List<ClaimComment> comments, List<ClaimLine> lines) {
        return new ClaimView(claim.getId(), claim.getPersonId(),
                claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
                log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
                claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
                claim.getTags(), claim.getVoidReason(),
                comments.stream().map(ClaimCommentView::of).toList(), claim.getSettleBatch(),
                lines.stream().map(ClaimLineView::of).toList(), claim.rateStamp(), claim.getReviewOn(),
                claim.isWaived());
    }
}

/** A line of a claim: its label, its quantity and its unit amount with two decimals. */
